mapper.select:
/* BaseinfoMapper."selectSystinfoList" */ SELECT A.SYST_VAL_CD AS systValCd , A.SYST_VAL_NM AS systValNm , A.SORT_IDX AS sortIdx , A.SYST_VAL_D_CD AS systValDCd , A.SYST_VAL_D_NM AS systValDNm FROM ( SELECT A.SYST_VAL_CD , A.SYST_VAL_NM , B.SORT_IDX AS SORT_IDX , B.SYST_VAL_D_CD , B.SYST_VAL_D_NM FROM TB_SYST_VAL_M A INNER JOIN TB_SYST_VAL_D B ON ( A.SYST_VAL_CD = B.SYST_VAL_CD
) WHERE 1=1
AND A.SYST_VAL_CD IN
#{item}
AND A.USE_YN = 'Y' AND A.USE_YN = B.USE_YN
UNION ALL
SELECT A.SYST_VAL_CD , A.SYST_VAL_NM , 0 AS SORT_IDX , NULL AS SYST_VAL_D_CD , '전체' AS SYST_VAL_D_NM FROM TB_SYST_VAL_M A WHERE 1=1 AND A.USE_YN = 'Y'
AND A.SYST_VAL_CD IN
#{item}
) A WHERE 1=1 ORDER BY A.SYST_VAL_CD, A.SORT_IDX, A.SYST_VAL_D_CD

/* BaseinfoMapper."selectSystinfo" */ SELECT A.SYST_VAL_CD AS systValCd , A.SYST_VAL_NM AS systValNm , B.SORT_IDX AS sortIdx , B.SYST_VAL_D_CD AS systValDCd , B.SYST_VAL_D_NM AS systValDNm FROM TB_SYST_VAL_M A INNER JOIN TB_SYST_VAL_D B ON ( A.SYST_VAL_CD = B.SYST_VAL_CD AND A.USE_YN = B.USE_YN
AND B.SYST_VAL_D_CD = #{codeD}
AND B.SYST_VAL_D_NM LIKE CONCAT('%', #{nameD}, '%')
) WHERE 1=1 AND A.USE_YN = 'Y'
AND A.SYST_VAL_CD = #{code}
ORDER BY A.SYST_VAL_CD, B.SORT_IDX, B.SYST_VAL_D_CD

/* BaseinfoMapper."selectBaseinfoList" */ SELECT A.BAIM_VAL_CD AS baimValCd , A.BAIM_VAL_NM AS baimValNm , A.SORT_IDX AS sortIdx , A.BAIM_VAL_D_CD AS baimValDCd , A.BAIM_VAL_D_NM AS baimBalDNm FROM ( SELECT A.BAIM_VAL_CD , A.BAIM_VAL_NM , B.SORT_IDX AS SORT_IDX , B.BAIM_VAL_D_CD , B.BAIM_VAL_D_NM FROM TB_BAIM_VAL_M A INNER JOIN TB_BAIM_VAL_D B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.BAIM_VAL_CD = B.BAIM_VAL_CD AND (B.VAL_D_INFO_1 != 'manage' OR B.VAL_D_INFO_1 IS NULL) ) WHERE 1=1 AND A.CMPNY_CD = #{cmpnyCd}
AND A.BAIM_VAL_CD IN
#{item}
AND A.USE_YN = 'Y' AND A.USE_YN = B.USE_YN
UNION ALL
SELECT A.BAIM_VAL_CD , A.BAIM_VAL_NM , 0 AS SORT_IDX , NULL AS BAIM_VAL_D_CD , '전체' AS BAIM_VAL_D_NM FROM TB_BAIM_VAL_M A WHERE 1=1 AND A.CMPNY_CD = #{cmpnyCd} AND A.USE_YN = 'Y'
AND A.BAIM_VAL_CD IN
#{item}
) A WHERE 1=1 ORDER BY A.BAIM_VAL_CD, A.SORT_IDX, A.BAIM_VAL_D_CD

/* BaseinfoMapper."selectBaseinfo" */ SELECT A.BAIM_VAL_CD AS baimValCd , A.BAIM_VAL_NM AS baimValNm , B.SORT_IDX AS sortIdx , B.BAIM_VAL_D_CD AS baimValDCd , B.BAIM_VAL_D_NM AS baimBalDNm FROM TB_BAIM_VAL_M A INNER JOIN TB_BAIM_VAL_D B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.BAIM_VAL_CD = B.BAIM_VAL_CD AND A.USE_YN = B.USE_YN
AND B.BAIM_VAL_D_CD = #{codeD}
AND B.BAIM_VAL_D_NM LIKE CONCAT('%', #{nameD}, '%')
AND (B.VAL_D_INFO_1 != 'manage' OR B.VAL_D_INFO_1 IS NULL) ) WHERE A.CMPNY_CD = #{cmpnyCd} AND A.USE_YN = 'Y'
AND A.BAIM_VAL_CD = #{code}
ORDER BY A.BAIM_VAL_CD, B.SORT_IDX, B.BAIM_VAL_D_CD

    /* BaseinfoMapper.getUserIdDupleCheck */
	(
		SELECT 
			'N' AS UNIQUE_YN
		FROM TB_USER
		WHERE 1=1
		  AND CMPNY_CD = #{cmpnyCd}
		  AND USER_ID = #{userId}
	)
	UNION
	(
		SELECT 'Y' FROM DUAL
	)
	LIMIT 1;

    /* BaseinfoMapper."selectMblUniqChk" */
    SELECT COUNT(*)
	FROM TB_USER A
	WHERE A.MBL_NO_HMAC = #{mblNoHmac}

mapper.insert:
    /* BaseinfoMapper.insertSmsAuthNo */
    INSERT INTO TB_SMS_AUTH_CODE (
		MBL_NO_ENC
		, MBL_NO_HMAC
	    , AUTH_CD
	    , EXPIRED_AT
	)
	VALUES (
		#{mblNoEnc}
		, #{mblNoHmac}
	    , #{certNo}
	    , DATE_ADD(NOW(), INTERVAL 1 MINUTE)
	)

mapper.select:
    /* BaseinfoMapper.selectCertNoSmsId */
    SELECT 
		SMS_ID
	FROM TB_SMS_AUTH_CODE
	WHERE 1=1
	  AND MBL_NO_HMAC = #{mblNoHmac}
	  AND AUTH_CD = #{certNo}
	  AND EXPIRED_AT  >=  NOW()
	  AND VERIFIED_YN = 'N'

mapper.update:
    /* BaseinfoMapper.updateSmsAuthReq */
    UPDATE TB_SMS_AUTH_CODE
	SET 
	    VERIFIED_YN = 'Y',
	    UPDATE_NO = 'SYSTEM',
	    UPDATE_DATE = NOW()
	WHERE 
		SMS_ID = #{smsId}
	    AND MBL_NO_HMAC = #{mblNoHmac}
	    AND AUTH_CD = #{certNo}
	    AND EXPIRED_AT  >=  NOW()
	    AND VERIFIED_YN = 'N'

mapper.select:
/* BaseinfoMapper."selectSiteInfoList" */ SELECT A.SITE_CD AS siteCd , A.SITE_NO AS siteNo , A.SITE_NM AS siteNm , A.SITE_ADMIN_CD AS siteAdminCd , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'USER_NM', A.SITE_ADMIN_CD, null) AS siteAdminNm , A.ADDR_1 AS addr1 , A.ADDR_2 AS addr2 , A.TEL_NO AS telNo FROM TB_SITE A
INNER JOIN TB_USER_SITE_AUTH B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.SITE_CD = B.SITE_CD AND B.USE_YN = 'Y' AND B.USER_CD = #{userCd} )
WHERE 1=1 AND A.CMPNY_CD = #{cmpnyCd} AND A.USE_YN = 'Y' AND ( A.END_DATE IS NULL OR A.END_DATE >= date_format(NOW(), '%y%m%d') )
AND A.SITE_NO = #{siteNo}
AND A.SITE_NM LIKE CONCAT('%', #{siteNm}, '%')

/* BaseinfoMapper."selectSiteNodeList" */ WITH RECURSIVE viewer AS ( SELECT U.CMPNY_CD, U.USER_CD, U.AUTH_CD, U.SITE_CD, U.NODE_CD FROM TB_USER U WHERE U.CMPNY_CD = #{cmpnyCd}
AND U.USER_CD = #{userCd}
LIMIT 1 ), node_tree AS ( /* 로그인 사용자의 node 부터 시작 */ SELECT N.CMPNY_CD, N.SITE_CD, N.NODE_CD FROM TB_SITE_NODE N INNER JOIN viewer V ON N.CMPNY_CD = V.CMPNY_CD AND N.SITE_CD = V.SITE_CD AND N.NODE_CD = V.NODE_CD
UNION ALL
/* 하위 노드 무한 확장 */ SELECT C.CMPNY_CD, C.SITE_CD, C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD )
SELECT A.CMPNY_CD AS cmpnyCd , A.SITE_CD AS siteCd , A.NODE_CD AS nodeCd , A.NODE_NM AS nodeNm , A.NODE_TYPE AS nodeType , A.PARENT_NODE_CD AS parentNodeCd , A.PARENT_NODE_NM AS parentNodeNm , A.SELF_ATTD_APPRV_YN AS selfAttdApprvYn FROM ( SELECT A.CMPNY_CD , A.SITE_CD , A.NODE_CD , A.NODE_NM , A.NODE_TYPE , PARENT_NODE_CD , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'NODE', A.SITE_CD, A.PARENT_NODE_CD) AS PARENT_NODE_NM , SELF_ATTD_APPRV_YN FROM TB_SITE_NODE A WHERE A.CMPNY_CD = #{cmpnyCd} AND A.SITE_CD = #{siteCd} AND (NULLIF(A.MAIN_ADMIN_CD, '') IS NOT NULL OR NULLIF(A.SUB_ADMIN_CD, '') IS NOT NULL) /* 권한별 노드/사이트 제한 */ AND ( (SELECT V.AUTH_CD FROM viewer V) IN ('system','master','hr','safe') OR ( CASE WHEN A.SITE_CD = (SELECT V.SITE_CD FROM viewer V) THEN (A.SITE_CD = (SELECT V.SITE_CD FROM viewer V) AND A.NODE_CD IN (SELECT T.NODE_CD FROM node_tree T)) END
) )
AND A.NODE_CD = #{nodeCd}
AND A.NODE_NM LIKE CONCAT('%', #{nodeNm}, '%')
AND A.NODE_TYPE = #{nodeType}
) A WHERE 1=1
AND A.PARENT_NODE_NM LIKE CONCAT('%', #{parentNodeNm}, '%')

/* BaseinfoMapper."selectUserIdInfo" */
SELECT
	CMPNY_CD	AS cmpnyCd
	, USER_CD	AS userCd
	, USER_ID	AS userId
FROM TB_USER
WHERE 1=1
  AND USER_NM = #{userNm}
  AND MBL_NO_HMAC = #{mblNoHmac}

mapper.update:
    /* BaseinfoMapper."updateUserPw" */
    UPDATE TB_USER
	SET USER_PW = #{userPw}
	WHERE 1=1
	  AND CMPNY_CD = #{cmpnyCd}
	  AND USER_CD = #{userCd}

mapper.select:
/* BaseinfoMapper.selectUserInfoList */ WITH RECURSIVE viewer AS ( SELECT U.CMPNY_CD, U.USER_CD, U.USER_ID, U.AUTH_CD, U.SITE_CD, U.NODE_CD FROM TB_USER U WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.USER_CD = #{gvUserCd} LIMIT 1 ), node_tree AS ( SELECT N.CMPNY_CD, N.SITE_CD, N.NODE_CD FROM TB_SITE_NODE N INNER JOIN viewer V ON N.CMPNY_CD = V.CMPNY_CD AND N.SITE_CD = V.SITE_CD AND N.NODE_CD = V.NODE_CD
UNION ALL
SELECT C.CMPNY_CD, C.SITE_CD, C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD )
SELECT null AS chk , A.CMPNY_CD AS cmpnyCd , A.USER_CD AS userCd , A.USER_ID AS userId , A.USER_NM AS userNm , A.AUTH_CD AS authCd , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'AUTH_LEVEL', A.AUTH_CD, null) AS authLevel , A.SITE_CD AS siteCd , A.NODE_CD AS nodeCd , A.NODE_CD AS oriNodeCd , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'NODE', A.SITE_CD, A.NODE_CD) AS nodeNm , C.SITE_NM AS siteNm , A.MBL_NO_ENC AS mblNo , A.EMAIL_ENC AS email , A.BIRTH_DT_ENC AS birthDt , A.GENDER AS gender , A.USE_YN AS useYn , IFNULL(B.SITE_NM_LIST, '') AS siteNmList , A.ACCOUNT_STATUS AS accountStatus , DATE_FORMAT(STR_TO_DATE(A.WITHDRAWAL_DATE, '%Y%m%d'), '%Y-%m-%d') AS withdrawalDate FROM TB_USER A LEFT JOIN ( SELECT X.USER_CD, GROUP_CONCAT(S.SITE_NM ORDER BY S.SITE_CD SEPARATOR ',') AS SITE_NM_LIST FROM TB_USER_SITE_AUTH X INNER JOIN TB_SITE S ON X.CMPNY_CD = S.CMPNY_CD AND X.SITE_CD = S.SITE_CD WHERE X.USE_YN = 'Y' GROUP BY X.USER_CD ) B ON ( B.USER_CD = A.USER_CD ) INNER JOIN TB_SITE C ON ( A.CMPNY_CD = C.CMPNY_CD AND A.SITE_CD = C.SITE_CD AND C.USE_YN = 'Y' ) WHERE 1=1 AND A.CMPNY_CD = #{gvCmpnyCd} AND A.AUTH_CD != 'system' AND A.USE_YN = 'Y'
AND (
(SELECT V.AUTH_CD FROM viewer V) IN ('system','master','hr') OR
(SELECT V.AUTH_CD FROM viewer V) IN ('system','master','hr','safe') OR
( A.SITE_CD = (SELECT V.SITE_CD FROM viewer V)
AND A.NODE_CD IN (SELECT T.NODE_CD FROM node_tree T)
) )
AND A.USER_NM LIKE CONCAT('%', #{userNm}, '%')
AND A.USER_ID = #{userId}
AND A.USE_YN = #{useYn}
AND A.SITE_CD = #{siteCd}
AND A.NODE_CD = #{nodeCd}
AND NOT EXISTS ( SELECT 1 FROM TB_SHIFT_SCH_TEAM_USER STU WHERE STU.CMPNY_CD = A.CMPNY_CD AND STU.SITE_CD = A.SITE_CD AND STU.USER_CD = A.USER_CD )
